
INSERT INTO public.service_translations (service_id, language_id, title, short_description, long_description, seo_title, meta_description)
VALUES
-- SEO Agency
('4ad975ec-db36-46ee-933e-c33b5c3b4cc9', 1, 'SEO Agency', 'Expert SEO agency driving organic growth through technical optimization, content strategy, and AI-powered visibility solutions.', '<h2>Leading SEO Agency for Sustainable Growth</h2><p>At Advisable, we are a results-driven <strong>SEO agency</strong> that combines technical expertise with creative strategy to deliver measurable organic growth. Our team of SEO specialists leverages cutting-edge tools and AI-powered insights to ensure your business ranks where it matters most.</p><h3>Our SEO Services</h3><ul><li><strong>Technical SEO Audits</strong> — Comprehensive site analysis covering crawlability, indexation, Core Web Vitals, and structured data implementation</li><li><strong>On-Page Optimization</strong> — Keyword research, content optimization, meta tag strategy, and internal linking architecture</li><li><strong>Off-Page SEO</strong> — Authority building through digital PR, strategic link acquisition, and brand mention optimization</li><li><strong>Local SEO</strong> — Google Business Profile optimization, local citation building, and geo-targeted content strategies</li><li><strong>AI & GEO Optimization</strong> — Preparing your brand for AI search engines and generative engine optimization</li></ul><h3>Why Choose Advisable as Your SEO Agency?</h3><p>We go beyond traditional SEO. Our approach integrates <a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility</a> strategies that position your brand for the future of search. From technical foundations to content excellence, we deliver comprehensive SEO solutions that drive real business results.</p><h3>Industries We Serve</h3><p>Our SEO expertise spans e-commerce, SaaS, B2B, healthcare, finance, and technology sectors. We tailor our strategies to your industry''s unique search landscape and competitive dynamics.</p>', 'SEO Agency | Advisable - Expert Search Engine Optimization', 'Leading SEO agency delivering organic growth through technical SEO, content strategy, and AI-powered visibility. Get measurable results with Advisable.'),

-- Performance Marketing Agency
('65138138-c27d-4290-9168-79c65f3862a1', 1, 'Performance Marketing Agency', 'Data-driven performance marketing agency maximizing ROI through paid search, social advertising, and conversion optimization.', '<h2>Performance Marketing Agency Built for Results</h2><p>Advisable is a <strong>performance marketing agency</strong> that turns ad spend into measurable business growth. We manage millions in ad budgets across Google, Meta, TikTok, and LinkedIn, optimizing every euro for maximum return.</p><h3>Our Performance Marketing Services</h3><ul><li><strong>Paid Search (PPC)</strong> — <a href="/digital-agency/google-ads-campaigns">Google Ads campaigns</a> engineered for conversion and efficiency</li><li><strong>Paid Social</strong> — <a href="/digital-agency/meta-ads-campaigns">Meta Ads</a>, TikTok, and LinkedIn advertising with precise audience targeting</li><li><strong>Programmatic Advertising</strong> — Automated media buying across premium display and video networks</li><li><strong>Conversion Rate Optimization</strong> — Landing page testing, funnel analysis, and UX improvements</li><li><strong>Attribution & Analytics</strong> — Multi-touch attribution modeling and performance dashboards</li></ul><h3>Our Approach to Performance Marketing</h3><p>We combine creative excellence with data science. Every campaign is built on rigorous audience research, A/B testing, and real-time optimization to ensure your marketing budget delivers maximum impact.</p>', 'Performance Marketing Agency | Advisable - Data-Driven Growth', 'Expert performance marketing agency maximizing ROI through Google Ads, Meta Ads, and conversion optimization. Drive measurable growth with Advisable.'),

-- Marketing Agency
('e45172d3-85fa-4264-8ca8-675e850b7084', 1, 'Marketing Agency', 'Full-service marketing agency offering integrated digital strategies, brand growth, and multi-channel campaign management.', '<h2>Full-Service Marketing Agency for Modern Brands</h2><p>Advisable is a <strong>marketing agency</strong> that blends strategy, creativity, and technology to accelerate brand growth. We provide end-to-end marketing solutions from brand positioning to campaign execution across all digital channels.</p><h3>Our Marketing Services</h3><ul><li><strong>Digital Strategy</strong> — Comprehensive marketing plans aligned with your business objectives</li><li><strong>Content Marketing</strong> — Blog content, thought leadership, and content distribution strategies</li><li><strong>Social Media Marketing</strong> — <a href="/digital-agency/social-media-management">Social media management</a> and community building</li><li><strong>Email Marketing</strong> — <a href="/digital-agency/email-marketing">Automated email campaigns</a> and lifecycle marketing</li><li><strong>Brand Strategy</strong> — Positioning, messaging, and visual identity development</li><li><strong>Marketing Analytics</strong> — Data-driven insights and reporting for continuous improvement</li></ul><h3>Why Partner with Advisable?</h3><p>As a marketing agency with deep expertise in both digital and traditional channels, we create integrated campaigns that build brand awareness, generate leads, and drive revenue growth.</p>', 'Marketing Agency | Advisable - Full-Service Digital Marketing', 'Full-service marketing agency delivering integrated digital strategies, brand growth, and multi-channel campaigns. Partner with Advisable for results.'),

-- Email Marketing Agency
('4b0b4bcd-6aae-47a1-84e1-b94c56c0d65a', 1, 'Email Marketing Agency', 'Specialized email marketing agency delivering automated campaigns, segmentation strategies, and high-converting email flows.', '<h2>Email Marketing Agency That Drives Revenue</h2><p>Advisable is an <strong>email marketing agency</strong> specializing in automated campaigns that nurture leads and drive conversions. Our <a href="/digital-agency/email-marketing">email marketing services</a> combine creative design with data-driven segmentation to maximize engagement and ROI.</p><h3>Our Email Marketing Services</h3><ul><li><strong>Email Strategy & Planning</strong> — Customer journey mapping and campaign calendar development</li><li><strong>Marketing Automation</strong> — Drip campaigns, triggered emails, and behavioral automation flows</li><li><strong>Email Design & Development</strong> — Responsive, on-brand email templates optimized for all devices</li><li><strong>List Management & Segmentation</strong> — Advanced audience segmentation for personalized messaging</li><li><strong>A/B Testing & Optimization</strong> — Subject line testing, send time optimization, and content experimentation</li><li><strong>Deliverability Management</strong> — Inbox placement optimization, domain reputation monitoring, and compliance</li></ul><h3>Platforms We Work With</h3><p>We are experts in Klaviyo, Mailchimp, HubSpot, ActiveCampaign, and custom SMTP solutions. Whatever your tech stack, we optimize your email channel for maximum performance.</p>', 'Email Marketing Agency | Advisable - Automated Campaigns', 'Expert email marketing agency delivering automated campaigns, segmentation, and high-converting flows. Maximize email ROI with Advisable.'),

-- eCommerce Agency
('934b1dc4-1ec3-420e-ac34-31cb1210a3a6', 1, 'eCommerce Agency', 'Expert eCommerce agency building high-converting online stores with Shopify, WooCommerce, and custom platforms.', '<h2>eCommerce Agency for High-Growth Online Stores</h2><p>Advisable is an <strong>eCommerce agency</strong> that builds, optimizes, and scales online stores. From platform selection to conversion optimization, our <a href="/digital-agency/e-commerce-solutions">eCommerce solutions</a> are designed to maximize your online revenue.</p><h3>Our eCommerce Services</h3><ul><li><strong>eCommerce Platform Development</strong> — Custom stores on Shopify, WooCommerce, Magento, and headless commerce architectures</li><li><strong>UX & Conversion Optimization</strong> — User experience design focused on reducing cart abandonment and increasing AOV</li><li><strong>Product Feed Management</strong> — Google Shopping, Meta Catalog, and marketplace feed optimization</li><li><strong>eCommerce SEO</strong> — Product page optimization, category architecture, and schema markup</li><li><strong>Payment & Checkout Optimization</strong> — Streamlined checkout flows and payment gateway integration</li></ul><h3>Why Choose Advisable for eCommerce?</h3><p>We combine technical development expertise with marketing know-how to create online stores that don''t just look great — they sell. Our data-driven approach ensures every design and development decision is tied to revenue outcomes.</p>', 'eCommerce Agency | Advisable - Online Store Experts', 'Expert eCommerce agency building high-converting stores with Shopify, WooCommerce, and custom platforms. Scale your online sales with Advisable.'),

-- Social Media Agency
('45f341d1-4a7c-4207-a694-a7fe7930555c', 1, 'Social Media Agency', 'Creative social media agency managing brand presence across Instagram, TikTok, LinkedIn, and Facebook with data-driven strategies.', '<h2>Social Media Agency for Brand Growth</h2><p>Advisable is a <strong>social media agency</strong> that helps brands build meaningful connections with their audiences. Our <a href="/digital-agency/social-media-management">social media management</a> services combine creative content with strategic distribution to grow your brand''s online presence.</p><h3>Our Social Media Services</h3><ul><li><strong>Social Media Strategy</strong> — Platform-specific strategies aligned with your brand goals and target audience</li><li><strong>Content Creation</strong> — Visual content, video production, and copywriting powered by our <a href="/digital-agency/ai-creative-studio">AI Creative Studio</a></li><li><strong>Community Management</strong> — Engagement, moderation, and reputation management across all platforms</li><li><strong>Paid Social Advertising</strong> — Targeted campaigns on Meta, TikTok, LinkedIn, and X</li><li><strong>Influencer Marketing</strong> — Influencer identification, outreach, and campaign management</li><li><strong>Analytics & Reporting</strong> — Performance tracking, competitive analysis, and ROI measurement</li></ul><h3>Platforms We Manage</h3><p>Instagram, TikTok, LinkedIn, Facebook, X (Twitter), YouTube, and Pinterest. We tailor our approach to each platform''s unique algorithm and audience behavior.</p>', 'Social Media Agency | Advisable - Content & Growth', 'Creative social media agency managing Instagram, TikTok, LinkedIn & Facebook. Data-driven strategies for brand growth. Partner with Advisable.'),

-- Web Design Agency
('b3f1d0ef-767d-44c0-b968-d122153f9b8b', 1, 'Web Design Agency', 'Creative web design agency crafting stunning, high-performance websites that convert visitors into customers.', '<h2>Web Design Agency for Modern Digital Experiences</h2><p>Advisable is a <strong>web design agency</strong> that creates beautiful, functional websites engineered for performance. Our <a href="/digital-agency/web-development">web development</a> team combines award-winning design with cutting-edge technology to deliver digital experiences that drive business results.</p><h3>Our Web Design Services</h3><ul><li><strong>Custom Website Design</strong> — Bespoke designs that reflect your brand identity and engage your audience</li><li><strong>Responsive Design</strong> — Mobile-first design ensuring flawless experiences across all devices</li><li><strong>UI/UX Design</strong> — User research, wireframing, prototyping, and usability testing</li><li><strong>WordPress & CMS Development</strong> — Custom WordPress themes and headless CMS implementations</li><li><strong>Landing Page Design</strong> — High-converting landing pages optimized for lead generation and sales</li><li><strong>Website Redesign</strong> — Modernizing existing sites with improved design, performance, and SEO</li></ul><h3>Our Design Process</h3><p>Every project starts with understanding your business goals and target audience. We use data-informed design decisions combined with creative excellence to build websites that are both visually stunning and technically superior.</p>', 'Web Design Agency | Advisable - Stunning Websites', 'Creative web design agency crafting high-performance websites. Custom design, responsive development & UX optimization. Build with Advisable.'),

-- PPC Agency
('f00319d9-c1ef-488d-8ef6-1d29098bfbc5', 1, 'PPC Agency', 'Expert PPC agency managing Google Ads, Microsoft Ads, and paid search campaigns for maximum return on ad spend.', '<h2>PPC Agency for Maximum ROI</h2><p>Advisable is a <strong>PPC agency</strong> that specializes in pay-per-click advertising across Google Ads, Microsoft Ads, and shopping platforms. Our <a href="/digital-agency/google-ads-campaigns">Google Ads management</a> delivers measurable results through data-driven campaign strategies.</p><h3>Our PPC Services</h3><ul><li><strong>Google Ads Management</strong> — Search, Display, Shopping, and YouTube advertising campaigns</li><li><strong>Microsoft Ads</strong> — Bing search advertising and audience network campaigns</li><li><strong>Shopping Campaigns</strong> — Google Shopping, Performance Max, and product feed optimization</li><li><strong>Remarketing</strong> — Dynamic remarketing and audience retargeting strategies</li><li><strong>PPC Audit & Strategy</strong> — Account structure review, keyword analysis, and competitive benchmarking</li><li><strong>Bid Management</strong> — Automated bidding strategies and manual bid optimization</li></ul><h3>Our PPC Approach</h3><p>We manage PPC campaigns with a focus on profitability, not just clicks. Every campaign is structured around your customer acquisition costs, lifetime value, and growth targets. Our certified Google Ads specialists ensure your budget works harder.</p>', 'PPC Agency | Advisable - Google Ads & Paid Search', 'Expert PPC agency managing Google Ads, Microsoft Ads & paid search. Maximize ROAS with data-driven campaigns. Get results with Advisable.');
